export function lessonFor(course,id){return LESSONS[course+'/'+id];}
export function frameMatches(frame,inputs){return Object.entries(frame.inputs).every(([k,v])=>inputs[k]===v);}
export function frameEvidence(lesson,e){return lesson.frames.map(frame=>e.trials.some(t=>!t.legacy&&t.frameId===frame.id&&frameMatches(frame,t.inputs)&&(!frame.empty||t.emptyReading===true&&!t.placed)&&(!frame.requiresBag||t.bag===true)&&(!lesson.requiresReading||t.studentReading===t.result.metrics.find(m=>m.key==='reading')?.value)));}
export function learningStatus(lesson,e){const evidence=frameEvidence(lesson,e),qs=[...lesson.questions,lesson.transfer],answers=qs.map(q=>Number(e.learning.answers[q.id])===q.correct&&Object.hasOwn(e.learning.answers,q.id));return {measured:evidence.filter(Boolean).length,required:evidence.length,evidence,checked:answers.filter(Boolean).length,questions:qs.length,complete:evidence.every(Boolean)&&answers.every(Boolean)&&e.note.trim().length>0&&(!lesson.plan||e.learning.plan.trim().length>0),humanReview:lesson.peer};}
export function drawingValid(points,inputs){if(!points)return false;const [x,y,endX,endY]=points,dx=endX-x;return x>=.39&&x<=.61&&y>=.32&&y<=.68&&Math.sign(dx)===inputs.direction&&Math.abs(Math.hypot(dx,endY-y)-inputs.magnitude*.075)<.035&&Math.abs(endY-y)<.06;}
